const Closeable = () => {
  const CloseTags = () => {
    const [tags, setTags] = useState(['react', 'typescript', 'dos', 'cga']);
    return (
      <TagGroup>
        {tags.map(tag => (
          <Tag
            key={tag}
            closeable
            onClose={() => setTags(prev => prev.filter(t => t !== tag))}
          >
            {tag}
          </Tag>
        ))}
        {tags.length === 0 && (
          <span style={{ color: '#5F340E', fontFamily: 'monospace', fontSize: '12px' }}>
            All tags removed
          </span>
        )}
      </TagGroup>
    );
  };
  return <CloseTags />;
